```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmName ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:Dhuen_Ki_Lakeer dbr:Night_of_the_Twelve }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dirDBP . }
  OPTIONAL { ?film dbo:director ?dirDBO . }
  BIND (COALESCE(?dirDBP, ?dirDBO) AS ?director)

  # director name (prefer dbp:name)
  OPTIONAL { ?director dbp:name ?dirNameDBP . }
  OPTIONAL { ?director rdfs:label ?dirLabel . FILTER (lang(?dirLabel) = "en") }
  BIND (COALESCE(?dirNameDBP, ?dirLabel) AS ?directorName)

  # director birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDBP . }
  OPTIONAL { ?director dbo:birthDate ?birthDBO . }
  BIND (COALESCE(?birthDBP, ?birthDBO) AS ?birthDate)

  # film name (prefer dbp:name)
  OPTIONAL { ?film dbp:name ?filmNameDBP . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
  BIND (COALESCE(?filmNameDBP, ?filmLabel) AS ?filmName)
}
LIMIT 100
